import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    albums = list(map(int, input[2:]))

    if max(albums) >= n:
        result = []
        for i in range(n):
            for j in range(m):
                if albums[j] > 0:
                    result.append(j + 1)
                    albums[j] -= 1
                    break
        print(" ".join(map(str, result)))
        return

    total_photos = sum(albums)
    if total_photos < n:
        print(-1)
        return

    # Sort albums by the number of photos in descending order
    albums_with_indices = sorted(enumerate(albums), key=lambda x: (-x[1], x[0]))
    albums_sorted = [x[1] for x in albums_with_indices]
    indices_sorted = [x[0] for x in albums_with_indices]

    result = []
    used = [0] * m
    for i in range(n):
        for j in range(m):
            index = indices_sorted[j]
            if albums_sorted[j] - used[index] > 0 and (not result or result[-1] != index + 1):
                result.append(index + 1)
                used[index] += 1
                break

    if len(result) == n:
        print(" ".join(map(str, result)))
    else:
        print(-1)

if __name__ == "__main__":
    main()
